solutionCode:
export async function classificarNumero(valor) {
  if (typeof valor !== 'number') {
    return Promise.reject(new Error('não é um número'));
  }
  if (valor > 0) {
    return Promise.resolve('positivo');
  }
  if (valor < 0) {
    return Promise.resolve('negativo');
  }
  return Promise.resolve('zero');
}
